/**
 * Migration 0004_calendar (plan m8 P26): the seven `calendar_` tables, GENERATED by drizzle-kit from
 * `apps/api/src/modules/calendar/schema.ts` (the eighth, `calendar_feed_tokens`, is 0005's: `db-calendar-feed-migration.test.ts`;
 * the table and index lists below read the fully migrated database, so they name it too). Applied to a scratch `file:` database through `@libsql/client` (never
 * `bun:sqlite`, a newer SQLite), then every CHECK is probed with one valid and one refused row, and the foreign keys
 * with their `ON DELETE` rules.
 */
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { type Client, type InValue, createClient } from "@libsql/client";
import { drizzle } from "drizzle-orm/libsql";
import { migrate } from "drizzle-orm/libsql/migrator";
import { MIGRATIONS_FOLDER } from "../src/db/migrate.ts";

const dir = mkdtempSync(join(tmpdir(), "toon-calendar-migration-"));
let client: Client;

beforeAll(async () => {
  client = createClient({ url: `file:${join(dir, "calendar.db")}` });
  await client.execute("PRAGMA foreign_keys = ON");
  await migrate(drizzle(client), { migrationsFolder: MIGRATIONS_FOLDER });
  await client.execute(
    "INSERT INTO users (id, email, name, password_hash, created_at, updated_at) VALUES ('u1', 'a@toon.test', 'A', 'h', 1, 1), ('u2', 'b@toon.test', 'B', 'h', 1, 1)",
  );
  await client.execute("INSERT INTO households (id, name, created_by, created_at, updated_at) VALUES ('h1', 'Familie', 'u1', 1, 1)");
});

afterAll(() => {
  client.close();
  rmSync(dir, { recursive: true, force: true });
});

async function scalar(sql: string, args: InValue[] = []): Promise<unknown> {
  return (await client.execute({ sql, args })).rows[0]?.[0];
}

let serial = 0;

/** Inserts a calendar entry with valid defaults overridden by `fields`; resolves the id. */
async function insertEntry(fields: Record<string, InValue> = {}): Promise<string> {
  serial += 1;
  const row: Record<string, InValue> = {
    id: `e${serial}`,
    household_id: "h1",
    kind: "event",
    title: "Termin",
    all_day: 1,
    start_date: "2027-01-05",
    end_date: "2027-01-05",
    created_at: 1,
    updated_at: 1,
    ...fields,
  };
  const columns = Object.keys(row);
  await client.execute({
    sql: `INSERT INTO calendar_entries (${columns.join(", ")}) VALUES (${columns.map(() => "?").join(", ")})`,
    args: columns.map((column) => row[column] ?? null),
  });
  return String(row.id);
}

/** The insert fails, naming the CHECK constraint. */
async function refused(insert: Promise<unknown>, constraint: string): Promise<void> {
  await expect(insert).rejects.toThrow(constraint);
}

describe("migration 0004_calendar", () => {
  test("it is the journal's fifth entry and creates the seven tables and their indexes (plus 0005's feed table, M9)", async () => {
    const journal = JSON.parse(readFileSync(join(MIGRATIONS_FOLDER, "meta/_journal.json"), "utf8")) as { entries: Array<{ tag: string }> };
    expect(journal.entries.map((entry) => entry.tag)).toEqual([
      "0000_core",
      "0001_recipe",
      "0002_finance",
      "0003_placeholder_members",
      "0004_calendar",
      "0005_calendar_feed",
    ]);
    const tables = (await client.execute("SELECT name FROM sqlite_master WHERE type = 'table' AND name LIKE 'calendar\\_%' ESCAPE '\\' ORDER BY name"))
      .rows.map((row) => String(row.name));
    expect(tables).toEqual([
      "calendar_entries",
      "calendar_entry_members",
      "calendar_feed_tokens",
      "calendar_occurrence_states",
      "calendar_resources",
      "calendar_waste_assignees",
      "calendar_waste_imports",
      "calendar_waste_settings",
    ]);
    const indexes = (await client.execute("SELECT name FROM sqlite_master WHERE type = 'index' AND tbl_name LIKE 'calendar\\_%' ESCAPE '\\' AND name NOT LIKE 'sqlite_%' ORDER BY name"))
      .rows.map((row) => String(row.name));
    expect(indexes).toEqual([
      "calendar_entries_household_freq_idx",
      "calendar_entries_household_start_idx",
      "calendar_entries_resource_idx",
      "calendar_entries_waste_import_idx",
      "calendar_entry_members_user_idx",
      "calendar_feed_tokens_household_user_uidx",
      "calendar_feed_tokens_token_hash_uidx",
      "calendar_feed_tokens_user_idx",
      "calendar_resources_household_idx",
      "calendar_waste_assignees_user_idx",
      "calendar_waste_imports_household_year_uidx",
    ]);
    expect(await scalar("PRAGMA foreign_key_check")).toBeUndefined();
  });

  test("calendar_entries: kind, freq, interval, assignee mode, category and detail", async () => {
    await insertEntry({ kind: "task", repeat_freq: "weekly", repeat_interval: 99, repeat_weekdays: "MO,TH", assignee_mode: "rotate" });
    await refused(insertEntry({ kind: "chore" }), "calendar_entries_kind");
    await refused(insertEntry({ repeat_freq: "hourly" }), "calendar_entries_repeat_freq");
    await refused(insertEntry({ repeat_interval: 0 }), "calendar_entries_repeat_interval");
    await refused(insertEntry({ repeat_interval: 100 }), "calendar_entries_repeat_interval");
    await refused(insertEntry({ assignee_mode: "all" }), "calendar_entries_assignee_mode");
    await insertEntry({ kind: "task", title: null, category: "waste_bio", category_detail: "bio_cleaning" });
    await refused(insertEntry({ category: "waste_glass" }), "calendar_entries_category");
    await refused(insertEntry({ category: "waste_bio", category_detail: "washing" }), "calendar_entries_category_detail");
  });

  test("calendar_entries: a title or a category, dates, times and their order", async () => {
    await refused(insertEntry({ title: null }), "calendar_entries_title_or_category");
    await refused(insertEntry({ start_date: "2027-1-5", end_date: "2027-01-05" }), "calendar_entries_start_date_format");
    await refused(insertEntry({ end_date: "05.01.2027" }), "calendar_entries_end_date_format");
    await refused(insertEntry({ end_date: "2027-01-04" }), "calendar_entries_date_order");
    await insertEntry({ all_day: 0, start_time: "08:00", end_time: "17:30" });
    await refused(insertEntry({ all_day: 0, start_time: "8:00" }), "calendar_entries_start_time_format");
    await refused(insertEntry({ all_day: 0, start_time: "08:00", end_time: "17:30:00" }), "calendar_entries_end_time_format");
    await insertEntry({ repeat_freq: "daily", repeat_until: "2027-12-31" });
    await refused(insertEntry({ repeat_freq: "daily", repeat_until: "2027-12" }), "calendar_entries_until_format");
  });

  test("calendar_entries: defaults for the rhythm and the assignee mode", async () => {
    const id = await insertEntry();
    const row = (await client.execute({ sql: "SELECT repeat_freq, repeat_interval, assignee_mode FROM calendar_entries WHERE id = ?", args: [id] })).rows[0];
    expect([row?.repeat_freq, row?.repeat_interval, row?.assignee_mode]).toEqual(["none", 1, "none"]);
  });

  test("calendar_entry_members: role CHECK, primary key, cascades from the entry and the user", async () => {
    const entry = await insertEntry({ kind: "task" });
    await client.execute({ sql: "INSERT INTO calendar_entry_members (entry_id, user_id, role, position) VALUES (?, 'u1', 'assignee', 0), (?, 'u2', 'assignee', 1)", args: [entry, entry] });
    await refused(
      client.execute({ sql: "INSERT INTO calendar_entry_members (entry_id, user_id, role) VALUES (?, 'u1', 'owner')", args: [entry] }),
      "calendar_entry_members_role",
    );
    await expect(
      client.execute({ sql: "INSERT INTO calendar_entry_members (entry_id, user_id, role) VALUES (?, 'u1', 'assignee')", args: [entry] }),
    ).rejects.toThrow();
    await client.execute({ sql: "DELETE FROM calendar_entries WHERE id = ?", args: [entry] });
    expect(await scalar("SELECT count(*) FROM calendar_entry_members WHERE entry_id = ?", [entry])).toBe(0);
  });

  test("calendar_occurrence_states: status and date CHECKs, done_by SET NULL, cascade from the entry", async () => {
    const entry = await insertEntry({ kind: "task" });
    await client.execute({
      sql: "INSERT INTO calendar_occurrence_states (entry_id, occurrence_date, status, done_by, updated_at) VALUES (?, '2027-01-05', 'done', 'u2', 1)",
      args: [entry],
    });
    await refused(
      client.execute({ sql: "INSERT INTO calendar_occurrence_states (entry_id, occurrence_date, status, updated_at) VALUES (?, '2027-01-06', 'open', 1)", args: [entry] }),
      "calendar_occurrence_states_status",
    );
    await refused(
      client.execute({ sql: "INSERT INTO calendar_occurrence_states (entry_id, occurrence_date, status, updated_at) VALUES (?, '6.1.2027', 'skipped', 1)", args: [entry] }),
      "calendar_occurrence_states_date_format",
    );
    await client.execute("INSERT INTO users (id, email, name, password_hash, created_at, updated_at) VALUES ('u3', 'c@toon.test', 'C', 'h', 1, 1)");
    await client.execute({ sql: "UPDATE calendar_occurrence_states SET done_by = 'u3' WHERE entry_id = ?", args: [entry] });
    await client.execute("DELETE FROM users WHERE id = 'u3'");
    expect(await scalar("SELECT count(*) FROM calendar_occurrence_states WHERE entry_id = ? AND done_by IS NULL", [entry])).toBe(1);
    await client.execute({ sql: "DELETE FROM calendar_entries WHERE id = ?", args: [entry] });
    expect(await scalar("SELECT count(*) FROM calendar_occurrence_states WHERE entry_id = ?", [entry])).toBe(0);
  });

  test("calendar_resources: kind CHECK; a booked car cannot be deleted (NO ACTION, checked at statement end)", async () => {
    await client.execute("INSERT INTO calendar_resources (id, household_id, name, created_at) VALUES ('car1', 'h1', 'Familienauto', 1)");
    expect(await scalar("SELECT kind FROM calendar_resources WHERE id = 'car1'")).toBe("car");
    await refused(client.execute("INSERT INTO calendar_resources (id, household_id, kind, name, created_at) VALUES ('bike', 'h1', 'bike', 'Rad', 1)"), "calendar_resources_kind");
    await insertEntry({ kind: "car", resource_id: "car1" });
    await expect(client.execute("DELETE FROM calendar_resources WHERE id = 'car1'")).rejects.toThrow();
  });

  test("calendar_waste_imports: provider, tour and source CHECKs, one import per (household, provider, year), entries cascade", async () => {
    const insert = (id: string, year: number, tour = 4, source = "upload", provider = "hattingen") =>
      client.execute({
        sql: "INSERT INTO calendar_waste_imports (id, household_id, provider, year, tour, source, source_name, entry_count, imported_at) VALUES (?, 'h1', ?, ?, ?, ?, 'flyer.pdf', 0, 1)",
        args: [id, provider, year, tour, source],
      });
    await insert("w2027", 2027);
    await refused(insert("bochum", 2028, 4, "upload", "bochum"), "calendar_waste_imports_provider");
    await refused(insert("t0", 2029, 0), "calendar_waste_imports_tour");
    await refused(insert("t10", 2029, 10), "calendar_waste_imports_tour");
    await refused(insert("mail", 2029, 4, "mail"), "calendar_waste_imports_source");
    await expect(insert("again", 2027)).rejects.toThrow("calendar_waste_imports");
    await insertEntry({ kind: "task", title: null, category: "waste_rest", waste_import_id: "w2027" });
    await client.execute("DELETE FROM calendar_waste_imports WHERE id = 'w2027'");
    expect(await scalar("SELECT count(*) FROM calendar_entries WHERE waste_import_id = 'w2027'")).toBe(0);
  });

  test("calendar_waste_settings and calendar_waste_assignees: CHECKs, primary keys, cascades", async () => {
    const settings = (tour: number, mode = "rotate", provider = "hattingen") =>
      client.execute({
        sql: "INSERT INTO calendar_waste_settings (household_id, provider, tour, assignee_mode, updated_at) VALUES ('h1', ?, ?, ?, 1)",
        args: [provider, tour, mode],
      });
    await refused(settings(0), "calendar_waste_settings_tour");
    await refused(settings(4, "everyone"), "calendar_waste_settings_assignee_mode");
    await refused(settings(4, "none", "bochum"), "calendar_waste_settings_provider");
    await settings(4);
    await client.execute("INSERT INTO calendar_waste_assignees (household_id, user_id, position) VALUES ('h1', 'u1', 0), ('h1', 'u2', 1)");
    await expect(client.execute("INSERT INTO calendar_waste_assignees (household_id, user_id, position) VALUES ('h1', 'u1', 2)")).rejects.toThrow();
    await client.execute("DELETE FROM calendar_waste_settings WHERE household_id = 'h1'");
    expect(await scalar("SELECT count(*) FROM calendar_waste_assignees")).toBe(0);
  });

  test("deleting the household cascades every calendar row, a car booking included", async () => {
    expect(await scalar("SELECT count(*) FROM calendar_entries WHERE household_id = 'h1' AND resource_id IS NOT NULL")).toBe(1);
    await client.execute("DELETE FROM households WHERE id = 'h1'");
    for (const table of ["calendar_entries", "calendar_resources", "calendar_waste_imports", "calendar_waste_settings"]) {
      expect(await scalar(`SELECT count(*) FROM ${table}`), table).toBe(0);
    }
  });
});
